blockAction.example:
// client: space no longer jumps, but your bind on it still fires
const { Controls, Key } = kcds.ui;

Controls.blockAction('jump');
Key.bind('space', () => kcds.core.Events.toServer('ring:bell'));

blockAction.exampleCs:
// client: space no longer jumps, but your bind on it still fires

Controls.BlockAction("jump");
Key.Bind("space", new Action(() => Events.ToServer("ring:bell")));

unblockAction.example:
// client: E does nothing for five seconds
const { Controls } = kcds.ui;

Controls.blockAction('use');
setTimeout(() => Controls.unblockAction('use'), 5000);

unblockAction.exampleCs:
// client: E does nothing for five seconds

Controls.BlockAction("use");
Timers.SetTimeout(() => Controls.UnblockAction("use"), 5000);

disable.example:
// client
const { Controls } = kcds.ui;

Controls.disable();
Controls.showCursor();
// ... a menu is open ...
Controls.hideCursor();
Controls.enable();

disable.exampleCs:
// client

Controls.Disable();
Controls.ShowCursor();
// ... a menu is open ...
Controls.HideCursor();
Controls.Enable();

enable.example:
// client: three seconds without control
const { Controls } = kcds.ui;

Controls.disable();
setTimeout(() => Controls.enable(), 3000);

enable.exampleCs:
// client: three seconds without control

Controls.Disable();
Timers.SetTimeout(() => Controls.Enable(), 3000);

cursorPosition.example:
// client: what is under the pointer
const { Controls, Camera } = kcds.ui;
Controls.showCursor();
setInterval(() => {
  const at = Controls.cursorPosition();
  if (at) {
    const ray = Camera.rayFromScreen({ x: at.x, y: at.y, range: 10 });
    console.log(ray?.target);
  }
}, 200);

cursorPosition.exampleCs:
// client: what is under the pointer
Controls.ShowCursor();
Timers.SetInterval(() =>
{
    var at = Controls.CursorPosition();
    if (!at.IsNull)
    {
        var ray = Camera.RayFromScreen(new { x = at["x"].AsNumber(), y = at["y"].AsNumber(), range = 10 });
        Log.Info(ray);
    }
}, 200);
